type Prioritas = "rendah" | "sedang" | "tinggi";
type Todo = { id: number; judul: string; selesai: boolean; prioritas: Prioritas };
type Result<T> = { ok: true; data: T } | { ok: false; error: string };

const PRIORITAS: readonly string[] = ["rendah", "sedang", "tinggi"];
function isTodo(x: unknown): x is Todo {
  return (
    typeof x === "object" && x !== null &&
    "id" in x && typeof x.id === "number" &&
    "judul" in x && typeof x.judul === "string" &&
    "selesai" in x && typeof x.selesai === "boolean" &&
    "prioritas" in x && typeof x.prioritas === "string" && PRIORITAS.includes(x.prioritas)
  );
}
function muat(teks: string): Result<Todo[]> {
  let data: unknown;
  try {
    data = JSON.parse(teks);
  } catch {
    return { ok: false, error: "JSON rusak" };
  }
  if (!Array.isArray(data) || !data.every(isTodo)) return { ok: false, error: "Isi tidak valid" };
  return { ok: true, data };
}
const simpanan = JSON.stringify([{ id: 1, judul: "Belajar JSON", selesai: false, prioritas: "tinggi" }]);
for (const teks of [simpanan, "[{", '[{"id":1}]']) {
  const h = muat(teks);
  console.log(h.ok ? `${h.data.length} todo dimuat` : h.error);
}

