type Pengaturan = { tema: "terang" | "gelap"; ukuran: number };
const BAWAAN: Pengaturan = { tema: "terang", ukuran: 14 };
function isPengaturan(x: unknown): x is Pengaturan {
  return (
    typeof x === "object" && x !== null &&
    "tema" in x && (x.tema === "terang" || x.tema === "gelap") &&
    "ukuran" in x && typeof x.ukuran === "number"
  );
}
function muatPengaturan(teks: string): Pengaturan {
  try {
    const data: unknown = JSON.parse(teks);
    return isPengaturan(data) ? data : BAWAAN;
  } catch {
    return BAWAAN;
  }
}
for (const teks of ['{"tema":"gelap","ukuran":16}', "{"]) {
  const p = muatPengaturan(teks);
  console.log(p.tema, p.ukuran);
}
